package org.example.screen;

import com.almasb.fxgl.entity.Entity;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.effect.DropShadow;
import javafx.scene.control.Label;
import javafx.scene.image.Image;
import javafx.scene.image.ImageView;
import javafx.scene.layout.Pane;
import javafx.scene.layout.StackPane;
import javafx.scene.paint.Color;
import org.example.config.GameConfig;
import org.example.entity.EntityFactory;
import org.example.entity.player.PlayerComponent;
import org.example.ui.AssetManager;
import org.example.ui.UIStyle;

import static com.almasb.fxgl.dsl.FXGL.entityBuilder;
import static com.almasb.fxgl.dsl.FXGL.getGameScene;

public class GameScreen extends Screen {

    private static final DropShadow TITLE_SHADOW = createShadow();
    private static final double BACKGROUND_PARALLAX = 0.2;

    private Entity player;
    private PlayerComponent playerComponent;
    private Entity ground;
    private Entity background;
    private StackPane hudRoot;
    private Pane parallaxBackground;

    public GameScreen() {
    }

    @Override
    public void init() {
        getGameScene().setBackgroundColor(Color.WHITE);

        parallaxBackground = createParallaxBackground();
        if (parallaxBackground != null) {
            getGameScene().addUINode(parallaxBackground);
        }

        hudRoot = new StackPane();
        hudRoot.setPickOnBounds(false);
        hudRoot.setPrefWidth(GameConfig.WINDOW_WIDTH);
        hudRoot.setPrefHeight(GameConfig.WINDOW_HEIGHT);

        Label titleLabel = new Label("Forest");
        titleLabel.setFont(AssetManager.getTitleFont());
        titleLabel.setTextFill(UIStyle.ACCENT_COLOR);
        titleLabel.setEffect(TITLE_SHADOW);
        titleLabel.setPadding(new Insets(14, 0, 0, 0));
        StackPane.setAlignment(titleLabel, Pos.TOP_CENTER);
        hudRoot.getChildren().add(titleLabel);
        getGameScene().addUINode(hudRoot);

        background = createScrollingBackground();

        ground = EntityFactory.createGround();

        player = EntityFactory.createPlayer();
        playerComponent = EntityFactory.getPlayerComponent(player);

        // Bind camera to player for side-scrolling
        getGameScene().getViewport().setBounds(0, 0, GameConfig.WORLD_WIDTH, GameConfig.WORLD_HEIGHT);
        getGameScene().getViewport().bindToEntity(player, GameConfig.WINDOW_WIDTH / 2.0, GameConfig.WINDOW_HEIGHT / 2.0);
    }

    private Pane createParallaxBackground() {
        Image bgImage = AssetManager.loadImage(AssetManager.MENU_BG);
        if (bgImage == null) {
            return null;
        }

        double imgW = bgImage.getWidth();
        double imgH = bgImage.getHeight();
        double scale = Math.max((double) GameConfig.WINDOW_WIDTH / imgW, (double) GameConfig.WINDOW_HEIGHT / imgH);
        double fitW = imgW * scale;
        double fitH = imgH * scale;

        int tiles = (int) Math.ceil((double) GameConfig.WORLD_WIDTH / fitW) + 2;
        Pane bgContainer = new Pane();
        bgContainer.setPrefSize(GameConfig.WORLD_WIDTH, GameConfig.WINDOW_HEIGHT);

        for (int i = 0; i < tiles; i++) {
            ImageView bgView = new ImageView(bgImage);
            bgView.setPreserveRatio(true);
            bgView.setFitWidth(fitW);
            bgView.setSmooth(false);
            bgView.setTranslateX(i * fitW);
            bgView.setTranslateY((GameConfig.WINDOW_HEIGHT - fitH) / 2.0);
            bgContainer.getChildren().add(bgView);
        }

        Pane clipPane = new Pane(bgContainer);
        clipPane.setPrefSize(GameConfig.WINDOW_WIDTH, GameConfig.WINDOW_HEIGHT);
        clipPane.setClip(new javafx.scene.shape.Rectangle(GameConfig.WINDOW_WIDTH, GameConfig.WINDOW_HEIGHT));
        return clipPane;
    }

    @Override
    public void update() {
        if (parallaxBackground != null) {
            double viewportX = getGameScene().getViewport().getX();
            parallaxBackground.setTranslateX(-viewportX * BACKGROUND_PARALLAX);
        }
    }

    @Override
    public void cleanup() {
        try {
            if (hudRoot != null) getGameScene().removeUINode(hudRoot);
        } catch (Exception ignored) {}
        try {
            if (player != null) player.removeFromWorld();
        } catch (Exception ignored) {}
        try {
            if (ground != null) ground.removeFromWorld();
        } catch (Exception ignored) {}
        try {
            if (background != null) background.removeFromWorld();
        } catch (Exception ignored) {}
        try {
            if (parallaxBackground != null) getGameScene().removeUINode(parallaxBackground);
        } catch (Exception ignored) {}
        player = null;
        playerComponent = null;
        hudRoot = null;
        parallaxBackground = null;
    }

    public PlayerComponent getPlayerComponent() {
        return playerComponent;
    }

    private static DropShadow createShadow() {
        DropShadow shadow = new DropShadow();
        shadow.setOffsetX(3);
        shadow.setOffsetY(3);
        shadow.setRadius(4);
        shadow.setColor(Color.web("#1C0F08"));
        return shadow;
    }
}

package org.example.screen;

import com.almasb.fxgl.entity.Entity;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.effect.DropShadow;
import javafx.scene.control.Label;
import javafx.scene.image.Image;
import javafx.scene.image.ImageView;
import javafx.scene.layout.Pane;
import javafx.scene.layout.StackPane;
import javafx.scene.paint.Color;
import org.example.config.GameConfig;
import org.example.entity.EntityFactory;
import org.example.entity.player.PlayerComponent;
import org.example.ui.AssetManager;
import org.example.ui.UIStyle;

import static com.almasb.fxgl.dsl.FXGL.entityBuilder;
import static com.almasb.fxgl.dsl.FXGL.getGameScene;

public class GameScreen extends Screen {

    private static final DropShadow TITLE_SHADOW = createShadow();
    private static final double BACKGROUND_PARALLAX = 0.2;

    private Entity player;
    private PlayerComponent playerComponent;
    private Entity ground;
    private Entity background;
    private StackPane hudRoot;
    private Pane parallaxBackground;

    public GameScreen() {
    }

    @Override
    public void init() {
        getGameScene().setBackgroundColor(Color.WHITE);

        parallaxBackground = createParallaxBackground();
        if (parallaxBackground != null) {
            getGameScene().addUINode(parallaxBackground);
        }

        hudRoot = new StackPane();
        hudRoot.setPickOnBounds(false);
        hudRoot.setPrefWidth(GameConfig.WINDOW_WIDTH);
        hudRoot.setPrefHeight(GameConfig.WINDOW_HEIGHT);

        Label titleLabel = new Label("Forest");
        titleLabel.setFont(AssetManager.getTitleFont());
        titleLabel.setTextFill(UIStyle.ACCENT_COLOR);
        titleLabel.setEffect(TITLE_SHADOW);
        titleLabel.setPadding(new Insets(14, 0, 0, 0));
        StackPane.setAlignment(titleLabel, Pos.TOP_CENTER);
        hudRoot.getChildren().add(titleLabel);
        getGameScene().addUINode(hudRoot);

        background = createScrollingBackground();

        ground = EntityFactory.createGround();

        player = EntityFactory.createPlayer();
        playerComponent = EntityFactory.getPlayerComponent(player);

        // Bind camera to player for side-scrolling
        getGameScene().getViewport().setBounds(0, 0, GameConfig.WORLD_WIDTH, GameConfig.WORLD_HEIGHT);
        getGameScene().getViewport().bindToEntity(player, GameConfig.WINDOW_WIDTH / 2.0, GameConfig.WINDOW_HEIGHT / 2.0);
    }

    private Pane createParallaxBackground() {
        Image bgImage = AssetManager.loadImage(AssetManager.MENU_BG);
        if (bgImage == null) {
            return null;
        }

        double imgW = bgImage.getWidth();
        double imgH = bgImage.getHeight();
        double scale = Math.max((double) GameConfig.WINDOW_WIDTH / imgW, (double) GameConfig.WINDOW_HEIGHT / imgH);
        double fitW = imgW * scale;
        double fitH = imgH * scale;

        int tiles = (int) Math.ceil((double) GameConfig.WORLD_WIDTH / fitW) + 2;
        Pane bgContainer = new Pane();
        bgContainer.setPrefSize(GameConfig.WORLD_WIDTH, GameConfig.WINDOW_HEIGHT);

        for (int i = 0; i < tiles; i++) {
            ImageView bgView = new ImageView(bgImage);
            bgView.setPreserveRatio(true);
            bgView.setFitWidth(fitW);
            bgView.setSmooth(false);
            bgView.setTranslateX(i * fitW);
            bgView.setTranslateY((GameConfig.WINDOW_HEIGHT - fitH) / 2.0);
            bgContainer.getChildren().add(bgView);
        }

        Pane clipPane = new Pane(bgContainer);
        clipPane.setPrefSize(GameConfig.WINDOW_WIDTH, GameConfig.WINDOW_HEIGHT);
        clipPane.setClip(new javafx.scene.shape.Rectangle(GameConfig.WINDOW_WIDTH, GameConfig.WINDOW_HEIGHT));
        return clipPane;
    }

    private Entity createScrollingBackground() {
        Image bgImage = AssetManager.loadImage(AssetManager.MENU_BG);
        if (bgImage == null) {
            return entityBuilder().at(0, 0).view(new Pane()).buildAndAttach();
        }

        double imgW = bgImage.getWidth();
        double imgH = bgImage.getHeight();
        double scale = Math.max((double) GameConfig.WINDOW_WIDTH / imgW, (double) GameConfig.WINDOW_HEIGHT / imgH);
        double fitW = imgW * scale;
        double fitH = imgH * scale;

        int tiles = (int) Math.ceil((double) GameConfig.WORLD_WIDTH / fitW) + 1;
        Pane bgContainer = new Pane();
        bgContainer.setPrefSize(GameConfig.WORLD_WIDTH, GameConfig.WINDOW_HEIGHT);

        for (int i = 0; i < tiles; i++) {
            ImageView bgView = new ImageView(bgImage);
            bgView.setPreserveRatio(true);
            bgView.setFitWidth(fitW);
            bgView.setSmooth(false);
            bgView.setTranslateX(i * fitW);
            bgView.setTranslateY((GameConfig.WINDOW_HEIGHT - fitH) / 2.0);
            bgContainer.getChildren().add(bgView);
        }

        return entityBuilder()
                .at(0, 0)
                .view(bgContainer)
                .buildAndAttach();
    }

    @Override
    public void update() {
        if (parallaxBackground != null) {
            double viewportX = getGameScene().getViewport().getX();
            parallaxBackground.setTranslateX(-viewportX * BACKGROUND_PARALLAX);
        }
    }

    @Override
    public void cleanup() {
        try {
            if (hudRoot != null) getGameScene().removeUINode(hudRoot);
        } catch (Exception ignored) {}
        try {
            if (player != null) player.removeFromWorld();
        } catch (Exception ignored) {}
        try {
            if (ground != null) ground.removeFromWorld();
        } catch (Exception ignored) {}
        try {
            if (background != null) background.removeFromWorld();
        } catch (Exception ignored) {}
        try {
            if (parallaxBackground != null) getGameScene().removeUINode(parallaxBackground);
        } catch (Exception ignored) {}
        player = null;
        playerComponent = null;
        hudRoot = null;
        parallaxBackground = null;
    }

    public PlayerComponent getPlayerComponent() {
        return playerComponent;
    }

    private static DropShadow createShadow() {
        DropShadow shadow = new DropShadow();
        shadow.setOffsetX(3);
        shadow.setOffsetY(3);
        shadow.setRadius(4);
        shadow.setColor(Color.web("#1C0F08"));
        return shadow;
    }
}

package org.example.entity.player;

import com.almasb.fxgl.entity.component.Component;
import com.almasb.fxgl.texture.Texture;
import javafx.scene.layout.StackPane;
import org.example.config.GameConfig;

import static com.almasb.fxgl.dsl.FXGL.getInput;
import static com.almasb.fxgl.dsl.FXGL.texture;

public class PlayerComponent extends Component {

    private double vy = 0;
    private boolean onGround = false;
    private boolean jumpReq = false;

    // Animation properties
    private double animationTimer = 0;
    private double animationFrameDuration = 0.15; // Duration per frame in seconds
    private int currentRunFrame = 0;
    private int currentIdleFrame = 0;
    private String lastAnimationState = "idle";

    // Key state tracking
    private boolean movingLeft = false;
    private boolean movingRight = false;
    private double lastMouseX = Double.NaN;

    private StackPane textureContainer;

    public void setTextureContainer(StackPane container) {
        this.textureContainer = container;
    }

    public void setMovingLeft(boolean moving) {
        this.movingLeft = moving;
    }

    public void setMovingRight(boolean moving) {
        this.movingRight = moving;
    }

    public void requestJump() {
        jumpReq = true;
    }

    @Override
    public void onUpdate(double tpf) {
        // Update position based on current key states
        if (movingLeft) {
            entity.translateX(-GameConfig.PLAYER_SPEED);
            clampX();
        }
        if (movingRight) {
            entity.translateX(GameConfig.PLAYER_SPEED);
            clampX();
        }

        vy += GameConfig.PLAYER_GRAVITY;
        entity.translateY(vy);

        if (entity.getY() < 0) {
            entity.setY(0);
            vy = 0;
        }

        if (entity.getY() + GameConfig.PLAYER_SIZE >= GameConfig.GROUND_Y) {
            entity.setY(GameConfig.GROUND_Y - GameConfig.PLAYER_SIZE);
            vy = 0;
            onGround = true;
        } else {
            onGround = false;
        }

        if (jumpReq) {
            if (onGround) {
                vy = GameConfig.PLAYER_JUMP_STRENGTH;
            }
            jumpReq = false;
        }

        // Face player toward mouse cursor (only when mouse moves)
        try {
            if (textureContainer != null) {
                double mouseX = getInput().getMouseXUI();
                if (Double.isNaN(lastMouseX) || Math.abs(mouseX - lastMouseX) >= 1.0) {
                    double viewportX = getGameScene().getViewport().getX();
                    double playerScreenX = (entity.getX() + GameConfig.PLAYER_SIZE / 2.0) - viewportX;
                    textureContainer.setScaleX(mouseX < playerScreenX ? -1 : 1);
                    lastMouseX = mouseX;
                }
            }
        } catch (Exception ignored) {
        }

        // Handle animation
        updateAnimation(tpf);
    }

    private void clampX() {
        if (entity.getX() < 0) {
            entity.setX(0);
        }
        if (entity.getX() + GameConfig.PLAYER_SIZE > GameConfig.WORLD_WIDTH) {
            entity.setX(GameConfig.WORLD_WIDTH - GameConfig.PLAYER_SIZE);
        }
    }

    private void updateAnimation(double tpf) {
        // Priority: jump (in air) > run > idle
        String currentState;

        if (!onGround) {
            currentState = "jump";
        } else if (movingLeft || movingRight) {
            currentState = "run";
        } else {
            currentState = "idle";
        }

        // Reset animation if state changed
        if (!currentState.equals(lastAnimationState)) {
            animationTimer = 0;
            currentRunFrame = 0;
            currentIdleFrame = 0;
            lastAnimationState = currentState;

            if (currentState.equals("jump")) {
                updatePlayerTexture("sprites/jump.png");
                return;
            }
        }

        animationTimer += tpf;

        if (currentState.equals("run")) {
            // Run animation: 3 frames
            if (animationTimer >= animationFrameDuration) {
                animationTimer -= animationFrameDuration;
                currentRunFrame = (currentRunFrame + 1) % 3;
                updatePlayerTexture("sprites/player_run" + (currentRunFrame + 1) + ".png");
            }
        } else if (currentState.equals("idle")) {
            // Idle animation: 2 frames (blink)
            if (animationTimer >= animationFrameDuration) {
                animationTimer -= animationFrameDuration;
                currentIdleFrame = (currentIdleFrame + 1) % 2;
                updatePlayerTexture("sprites/player_idle" + (currentIdleFrame + 1) + ".png");
            }
        }
    }

    private void updatePlayerTexture(String textureName) {
        if (textureContainer == null) {
            return;
        }
        try {
            textureContainer.getChildren().clear();
            Texture newTexture = texture(textureName, GameConfig.PLAYER_SIZE, GameConfig.PLAYER_SIZE);
            textureContainer.getChildren().add(newTexture);
        } catch (Exception e) {
            // If texture loading fails, keep current texture
        }
    }
}

package org.example.entity.player;

import com.almasb.fxgl.entity.component.Component;
import com.almasb.fxgl.texture.Texture;
import javafx.scene.layout.StackPane;
import org.example.config.GameConfig;

import static com.almasb.fxgl.dsl.FXGL.getGameScene;
import static com.almasb.fxgl.dsl.FXGL.getInput;
import static com.almasb.fxgl.dsl.FXGL.texture;

public class PlayerComponent extends Component {

    private double vy = 0;
    private boolean onGround = false;
    private boolean jumpReq = false;

    // Animation properties
    private double animationTimer = 0;
    private double animationFrameDuration = 0.15; // Duration per frame in seconds
    private int currentRunFrame = 0;
    private int currentIdleFrame = 0;
    private String lastAnimationState = "idle";

    // Key state tracking
    private boolean movingLeft = false;
    private boolean movingRight = false;
    private double lastMouseX = Double.NaN;

    private StackPane textureContainer;

    public void setTextureContainer(StackPane container) {
        this.textureContainer = container;
    }

    public void setMovingLeft(boolean moving) {
        this.movingLeft = moving;
    }

    public void setMovingRight(boolean moving) {
        this.movingRight = moving;
    }

    public void requestJump() {
        jumpReq = true;
    }

    @Override
    public void onUpdate(double tpf) {
        // Update position based on current key states
        if (movingLeft) {
            entity.translateX(-GameConfig.PLAYER_SPEED);
            clampX();
        }
        if (movingRight) {
            entity.translateX(GameConfig.PLAYER_SPEED);
            clampX();
        }

        vy += GameConfig.PLAYER_GRAVITY;
        entity.translateY(vy);

        if (entity.getY() < 0) {
            entity.setY(0);
            vy = 0;
        }

        if (entity.getY() + GameConfig.PLAYER_SIZE >= GameConfig.GROUND_Y) {
            entity.setY(GameConfig.GROUND_Y - GameConfig.PLAYER_SIZE);
            vy = 0;
            onGround = true;
        } else {
            onGround = false;
        }

        if (jumpReq) {
            if (onGround) {
                vy = GameConfig.PLAYER_JUMP_STRENGTH;
            }
            jumpReq = false;
        }

        // Face player toward mouse cursor (only when mouse moves)
        try {
            if (textureContainer != null) {
                double mouseX = getInput().getMouseXUI();
                if (Double.isNaN(lastMouseX) || Math.abs(mouseX - lastMouseX) >= 1.0) {
                    double viewportX = getGameScene().getViewport().getX();
                    double playerScreenX = (entity.getX() + GameConfig.PLAYER_SIZE / 2.0) - viewportX;
                    textureContainer.setScaleX(mouseX < playerScreenX ? -1 : 1);
                    lastMouseX = mouseX;
                }
            }
        } catch (Exception ignored) {
        }

        // Handle animation
        updateAnimation(tpf);
    }

    private void clampX() {
        if (entity.getX() < 0) {
            entity.setX(0);
        }
        if (entity.getX() + GameConfig.PLAYER_SIZE > GameConfig.WORLD_WIDTH) {
            entity.setX(GameConfig.WORLD_WIDTH - GameConfig.PLAYER_SIZE);
        }
    }

    private void updateAnimation(double tpf) {
        // Priority: jump (in air) > run > idle
        String currentState;

        if (!onGround) {
            currentState = "jump";
        } else if (movingLeft || movingRight) {
            currentState = "run";
        } else {
            currentState = "idle";
        }

        // Reset animation if state changed
        if (!currentState.equals(lastAnimationState)) {
            animationTimer = 0;
            currentRunFrame = 0;
            currentIdleFrame = 0;
            lastAnimationState = currentState;

            if (currentState.equals("jump")) {
                updatePlayerTexture("sprites/jump.png");
                return;
            }
        }

        animationTimer += tpf;

        if (currentState.equals("run")) {
            // Run animation: 3 frames
            if (animationTimer >= animationFrameDuration) {
                animationTimer -= animationFrameDuration;
                currentRunFrame = (currentRunFrame + 1) % 3;
                updatePlayerTexture("sprites/player_run" + (currentRunFrame + 1) + ".png");
            }
        } else if (currentState.equals("idle")) {
            // Idle animation: 2 frames (blink)
            if (animationTimer >= animationFrameDuration) {
                animationTimer -= animationFrameDuration;
                currentIdleFrame = (currentIdleFrame + 1) % 2;
                updatePlayerTexture("sprites/player_idle" + (currentIdleFrame + 1) + ".png");
            }
        }
    }

    private void updatePlayerTexture(String textureName) {
        if (textureContainer == null) {
            return;
        }
        try {
            textureContainer.getChildren().clear();
            Texture newTexture = texture(textureName, GameConfig.PLAYER_SIZE, GameConfig.PLAYER_SIZE);
            textureContainer.getChildren().add(newTexture);
        } catch (Exception e) {
            // If texture loading fails, keep current texture
        }
    }
}
